"use client";
import { useState } from "react";
import { BookingChat } from "./BookingChat";
import { BookingForm } from "./BookingForm";
import { cx, Notice } from "./ui";

type Props = {
  slug: string; agentName: string; greeting: string; aiEnabled: boolean; bookingEnabled: boolean; contact: string;
  today: string; maxDate: string; maxParty: number; partyWord: string; services: { id: string; name: string }[]; suggestions: string[];
};

export function BookingExperience(p: Props) {
  const [tab, setTab] = useState<"chat" | "form">(p.aiEnabled ? "chat" : "form");
  const [nudge, setNudge] = useState(false);

  if (!p.bookingEnabled) {
    return <Notice tone="warn">Online reservations are paused at the moment.{p.contact ? ` Please contact us: ${p.contact}.` : ""}</Notice>;
  }
  const tabBtn = (id: "chat" | "form", label: string) => (
    <button type="button" role="tab" aria-selected={tab === id} onClick={() => setTab(id)}
      className={cx("min-h-11 flex-1 rounded-xl px-3 text-[15px] font-semibold", tab === id ? "bg-white text-ink ring-1 ring-line" : "text-ink-soft")}>{label}</button>
  );
  return (
    <div>
      {p.aiEnabled && (
        <div role="tablist" aria-label="How would you like to book?" className="mb-3 flex gap-1 rounded-2xl bg-[#e6edf7] p-1 lg:hidden">
          {tabBtn("chat", `Chat with ${p.agentName}`)}
          {tabBtn("form", "Booking form")}
        </div>
      )}
      <div className={cx("grid gap-5", p.aiEnabled && "lg:grid-cols-[1.1fr_1fr]")}>
        {p.aiEnabled && (
          <section aria-label={`Chat with ${p.agentName}`} className={cx("overflow-hidden rounded-3xl bg-[#eaf1fb] ring-1 ring-line lg:block lg:h-[38rem]", tab !== "chat" && "hidden")}>
            <BookingChat slug={p.slug} agentName={p.agentName} greeting={p.greeting} suggestions={p.suggestions} onDegraded={() => setNudge(true)} />
          </section>
        )}
        <section aria-label="Booking form" className={cx("rounded-3xl bg-white ring-1 ring-line lg:block", p.aiEnabled && tab !== "form" && "hidden", nudge && "ring-2 ring-brand")}>
          <h2 className="px-5 pt-5 text-xl font-bold">{p.aiEnabled ? "Or book with the form" : "Book a reservation"}</h2>
          <BookingForm slug={p.slug} today={p.today} maxDate={p.maxDate} maxParty={p.maxParty} partyWord={p.partyWord} services={p.services} />
        </section>
      </div>
    </div>
  );
}
